import GSTStatecodeList from "@/JsonFiles/GSTStatecodeList.json";
import CountryList from "@/JsonFiles/CountryList.json";
// import AddGeoLocation from "./AddGeoLocation.vue";
import { Auth } from "aws-amplify";
import { uploadToS3 } from "@/mixins/S3PutStorageFile.js";
import { aseet_suppliers } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    supplieredition: Boolean,
    supplierItem: Object
  },
  components: {
    GSTStatecodeList,
    CountryList
    // AddGeoLocation,
  },
  data() {
    return {
      rules: {
        required: value => !!value || "This field is required",
        phone: val => (val ? val.length >= 8 : false) || "Phone number must be at least 8 digits",
        email: value => {
          const pattern = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
          return pattern.test(value) || "Invalid Email";
        }
      },
      billingName: "",
      billingAddress: "",
      mailingAddress: "",
      minDate: new Date().toISOString().substr(0, 10),
      date: new Date().toISOString().substr(0, 10),
      menu: false,
      cinCode: "",
      address1: "",
      address2: "",
      PrimaryName: "",
      PrimaryContact: "",
      PrimaryEmail: "",
      SecondaryName: "",
      SecondaryuserCCcode: "+91",
      SecondarycountryCodes: [],
      SecondaryContact: "",
      SecondaryEmail: "",
      gstin: "",
      pan: "",
      cinId: "",
      gstIsPdf: false,
      gstPreviewUrl: null,
      gstFileName: "",
      gstImageUrl: null,
      panFileName: "",
      panImageUrl: null,
      panIsPdf: false,
      panPreviewUrl: null,
      selectedFirmType: "",
      firmTypes: [{
        title: "Proprietorship",
        value: "proprietorship"
      }, {
        title: "Un-Registered Vendor",
        value: "unregisted_vendor"
      }, {
        title: "Private Limited (Pvt Ltd)",
        value: "private_limited"
      }, {
        title: "Partnership",
        value: "partnership"
      }, {
        title: "Limited Liability Partnership (LLP)",
        value: "llp"
      }, {
        title: "OPC Private Limited",
        value: "opc"
      }, {
        title: "Public Limited",
        value: "public_limited"
      }, {
        title: "NGO/Charity",
        value: "ngo"
      }, {
        title: "Labour",
        value: "labour"
      }],
      gstCodelist: [],
      gststateCode: "",
      headers: [{
        title: "Contact Name",
        value: "contact_Name",
        sortable: true
      }, {
        title: "Phone Number",
        value: "contact_number",
        sortable: true
      }, {
        title: "Email ID",
        value: "email_id",
        sortable: true
      }, {
        title: "Actions",
        value: "actions",
        sortable: true
      }],
      tableData: [],
      countryCodes: [],
      search: "",
      searchA: "",
      userCCcode: "+91",
      addAdditionalDialog: false,
      componentCheck: 0,
      accountName: "",
      branchName: "",
      accountNumber: "",
      accountType: "",
      ifscCode: "",
      tableLoading: false,
      fixed: true,
      addGeoLocationDialog: false,
      location_type: "",
      loading: false
    };
  },
  watch: {
    supplieredition: {
      async handler() {
        if (this.supplieredition == true) {
          this.billingName = this.supplierItem.supplier_name;
          this.PrimaryName = this.supplierItem.suppliers_contact_name;
          this.address1 = this.supplierItem.suppliers_address;
          this.address2 = this.supplierItem.suppliers_address_2;
          this.selectedFirmType = this.supplierItem.firm_type;
          this.cinId = this.supplierItem.cin_code;
          const rawDate = this.supplierItem.working_since;
          this.date = rawDate && !isNaN(Date.parse(rawDate)) ? new Date(rawDate).toISOString().substr(0, 10) : new Date().toISOString().substr(0, 10);
          this.PrimaryEmail = this.supplierItem.suppliers_email_id;
          const contact = this.supplierItem.suppliers_full_number;
          if (contact && (contact.includes("_") || contact.includes("-"))) {
            const separator = contact.includes("_") ? "_" : "-";
            const [code, number] = contact.split(separator);
            this.userCCcode = code;
            this.PrimaryContact = number;
          } else if (contact && contact.startsWith("+") && contact.length > 3) {
            this.userCCcode = contact.slice(0, 3); // e.g., +91
            this.PrimaryContact = contact.slice(3);
          } else {
            this.userCCcode = "";
            this.PrimaryContact = contact || "";
          }
          this.SecondaryName = this.supplierItem.secondary_contact_name;
          this.SecondaryEmail = this.supplierItem.secondary_email_id;
          const contact1 = this.supplierItem.secondary_contact_no;
          if (contact1 && (contact1.includes("_") || contact1.includes("-"))) {
            const separator1 = contact1.includes("_") ? "_" : "-";
            const [code1, number1] = contact1.split(separator1);
            this.SecondaryuserCCcode = code1;
            this.SecondaryContact = number1;
          } else if (contact1 && contact1.startsWith("+") && contact1.length > 3) {
            this.SecondaryuserCCcode = contact1.slice(0, 3); // e.g., +91
            this.SecondaryContact = contact1.slice(3);
          } else {
            this.SecondaryuserCCcode = "";
            this.SecondaryContact = contact1 || "";
          }
          this.accountNumber = this.supplierItem.bank_account_no;
          this.ifscCode = this.supplierItem.ifsc_code;
          this.accountName = this.supplierItem.account_holder_name;
          this.accountType = this.supplierItem.account_type;
          this.branchName = this.supplierItem.bank_branch_name;
          this.gststateCode = this.supplierItem.gst_state_code;
          this.pan = this.supplierItem.pan_no;
          this.gstFileName = this.getFileNameFromUrl(this.supplierItem.gst_certificate_doccument);
          this.panFileName = this.getFileNameFromUrl(this.supplierItem.pan_doccument);
          this.panImageUrl = this.supplierItem.pan_doccument;
          this.panPreviewUrl = this.supplierItem.pan_doccument;
          this.gstin = this.supplierItem.gst_no;
          this.gstImageUrl = this.supplierItem.gst_certificate_doccument;
          this.gstPreviewUrl = this.supplierItem.gst_certificate_doccument;
          this.Primarydesig = this.supplierItem.designation;
          this.gstIsPdf = this.supplierItem.gst_certificate_doccument?.endsWith(".pdf");
          this.panIsPdf = this.supplierItem.pan_doccument?.endsWith(".pdf");
        }
      },
      immediate: true
    }
  },
  computed: {
    formattedDate() {
      if (!this.date) return "";
      const d = new Date(this.date);
      const day = String(d.getDate()).padStart(2, "0");
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const year = d.getFullYear();
      return `${day}-${month}-${year}`;
    }
  },
  created() {
    this.countries();
    this.gstStates();
  },
  methods: {
    getFileNameFromUrl(url) {
      return url ? url.split("/").pop() : "";
    },
    cancelDate() {
      const rawDate = this.supplierItem.working_since;
      this.date = rawDate && !isNaN(Date.parse(rawDate)) ? new Date(rawDate).toISOString().substr(0, 10) : new Date().toISOString().substr(0, 10);
      this.menu = false;
    },
    gstinRule(value) {
      if (!value) return true; // Not mandatory
      const gstRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
      return gstRegex.test(value) || "Enter a valid GSTIN";
    },
    panRule(value) {
      if (!value) return true; // Optional
      const panRegex = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;
      return panRegex.test(value) || "Enter a valid PAN (e.g., ABCDE1234F)";
    },
    cinRule(value) {
      if (!value) return true; // Optional
      const cinRegex = /^L[0-9]{5}[A-Z]{2}[0-9]{4}[A-Z]{3}[0-9]{6}$/;
      return cinRegex.test(value) || "Enter a valid CIN (21-character format)";
    },
    countries() {
      var countryWithCc = [];
      this.countriesData = [];
      CountryList.forEach(element => {
        countryWithCc.push({
          title: element.dial_code,
          value: element.dial_code
        });
        this.countriesData.push(element.name);
      });
      var countryListt = countryWithCc;
      this.countryCodes = countryListt;
      this.SecondarycountryCodes = countryListt;
    },
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    add_geolocation(item) {
      this.location_type = item;
      this.addGeoLocationDialog = true;
      this.componentCheck = 1;
    },
    handleLocationSave(value) {
      // console.log(value);
      if (value.location_type === "ADDRESS_1") {
        this.address1 = value.address_Detail;
        this.addGeoLocationDialog = false;
      } else if (value.location_type === "ADDRESS_2") {
        this.address2 = value.address_Detail;
        this.addGeoLocationDialog = false;
      }
    },
    gstStates() {
      this.gstCodelist = GSTStatecodeList.map(item => ({
        ...item,
        title: `${item.text} (${item.value})`
      }));
    },
    add_address() {
      this.addAdditionalDialog = true;
      this.componentCheck = 1;
    },
    async Validate_Data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        const hasPanOrgst = this.panImageUrl || this.gstImageUrl;
        if (hasPanOrgst) {
          this.loading = true;
          this.get_file();
        } else {
          this.loading = true;
          this.create_supplier();
        }
      }
    },
    async get_file() {
      let files = [];
      if (this.panImageUrl) {
        files.push({
          file: this.panImageUrl,
          type: "pan"
        });
      }
      if (this.gstImageUrl) {
        files.push({
          file: this.gstImageUrl,
          type: "gst"
        });
      }
      const uploadPromises = files.map(({
        file,
        type
      }) => this.upload_new_func(file, type));
      try {
        await Promise.all(uploadPromises);
        this.create_supplier();
      } catch (error) {
        console.error("Error uploading images:", error);
        this.$emit("errorMsg", "PAN/gst upload failed.");
      }
    },
    async upload_new_func(fileUrl, type) {
      try {
        // Convert base64 data URL to Blob
        const response = await fetch(fileUrl);
        const blob = await response.blob();

        // Determine file extension from MIME type
        const mimeType = blob.type;
        const extension = mimeType.split("/")[1]; // e.g., 'png', 'jpeg', 'pdf'
        const fileName = `${type}.${extension}`;

        // AWS auth
        await Auth.currentCredentials();
        const orgDetails = this.$store.getters.GetOrgDetails;
        const s3_details = {
          bucket_name: "stichh-medias",
          region: "us-east-1"
        };
        const key = [`customers/${orgDetails.organization.organization_id}/${Date.now()}-${fileName}`];
        const fileUrlFromS3 = await uploadToS3(blob, s3_details, key);
        if (fileUrlFromS3) {
          if (type === "pan") this.panImageUrl = fileUrlFromS3;
          if (type === "gst") this.gstImageUrl = fileUrlFromS3;
        }
      } catch (err) {
        throw new Error(`Upload failed for ${type}: ${err.message}`);
      }
    },
    cancelAction() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    triggerFileInput(type) {
      if (type === "gst") {
        this.$refs.gstInput.click();
      } else if (type === "pan") {
        this.$refs.panInput.click();
      }
    },
    uploadImage(type, event) {
      const file = event.target.files[0];
      if (file) {
        const isPdf = file.type === "application/pdf";
        const reader = new FileReader();
        reader.onload = e => {
          if (type === "gst") {
            this.gstFileName = file.name;
            this.gstIsPdf = isPdf;
            this.gstPreviewUrl = e.target.result;
            this.gstImageUrl = e.target.result;
          } else if (type === "pan") {
            this.panFileName = file.name;
            this.panIsPdf = isPdf;
            this.panPreviewUrl = e.target.result;
            this.panImageUrl = e.target.result;
          }
        };
        reader.readAsDataURL(file);
      }
    },
    removeImage(type) {
      if (type === "gst") {
        this.gstImageUrl = null;
        this.gstFileName = "";
        this.gstIsPdf = false;
        this.gstPreviewUrl = null;
      } else if (type === "pan") {
        this.panFileName = "";
        this.panImageUrl = null;
        this.panIsPdf = false;
        this.panPreviewUrl = null;
      }
    },
    async create_supplier() {
      // let abc = this.panImageUrl;
      // console.log("aaa",abc)
      this.loading = true;
      const fullNumber = `${this.userCCcode}_${this.PrimaryContact}`;
      const SecondaryFullNumber = `${this.SecondaryuserCCcode}_${this.SecondaryContact}`;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(aseet_suppliers, {
          input: {
            action_type: "UPDATE_SUPPLIER",
            user_email_id: data.user.user_email_id,
            suppliers_id: this.supplierItem.suppliers_id,
            supplier_name: this.billingName == "" ? "N/A" : this.billingName,
            suppliers_contact_name: this.PrimaryName == "" ? "N/A" : this.PrimaryName,
            suppliers_full_number: fullNumber,
            suppliers_email_id: this.PrimaryEmail == "" ? "N/A" : this.PrimaryEmail,
            suppliers_address: this.address1 == "" ? "N/A" : this.address1,
            suppliers_address_2: this.address2 == "" ? "N/A" : this.address2,
            bank_account_no: this.accountNumber == "" ? "N/A" : this.accountNumber,
            gst_no: this.gstin == "" ? "N/A" : this.gstin,
            ifsc_code: this.ifscCode == "" ? "N/A" : this.ifscCode,
            account_holder_name: this.accountName == "" ? "N/A" : this.accountName,
            account_type: this.accountType == "" ? "N/A" : this.accountType,
            bank_branch_name: this.branchName == "" ? "N/A" : this.branchName,
            secondary_contact_name: this.SecondaryName == "" ? "N/A" : this.SecondaryName,
            secondary_contact_no: this.SecondaryContact == "" ? "N/A" : SecondaryFullNumber,
            secondary_email_id: this.SecondaryEmail == "" ? "N/A" : this.SecondaryEmail,
            gst_state_code: this.gststateCode == "" ? "N/A" : this.gststateCode,
            pan_no: this.pan == "" ? "N/A" : this.pan,
            pan_doccument: this.panImageUrl ? this.panImageUrl : "N/A",
            gst_certificate_doccument: this.gstImageUrl ? this.gstImageUrl : "N/A",
            firm_type: this.selectedFirmType == "" ? "N/A" : this.selectedFirmType,
            cin_code: this.cinId == "" ? "N/A" : this.cinId,
            working_since: this.date
          }
        }));
        var response = JSON.parse(result.data.aseet_suppliers);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
